def diheds(grid,n,m):
    # yield (transform name, f(row,col)->(row,col)) and transformed grids
    def h(g): return [r[::-1] for r in g]   # horizontal flip (mirror within width n)
    def v(g): return g[::-1]                 # vertical flip (within height m)
    def rot180(g): return [r[::-1] for r in g[::-1]]
    def tr(g): return [r[::-1] for r in g[::-1]]
    def t90(g):
        pass
    res={
      'h':h,[h(g) for g in [grid]],
      'v':v,[v(g) for g in [grid]],
      'r180':rot180,[rot180(grid)],
    }
    return res

